<?php
namespace App\Controllers;
use App\Core\{Controller,Database,Auth,Request,Response};
final class PortalAdminController extends Controller {
    public function index():void{if(!Auth::can('portal.manage')){http_response_code(403);require BASE_PATH.'/app/Views/errors/403.php';return;}$db=Database::connection();$t=Auth::tenantId();$u=$db->prepare("SELECT pu.*,c.name customer_name FROM customer_portal_users pu JOIN customers c ON c.id=pu.customer_id AND c.tenant_id=pu.tenant_id WHERE pu.tenant_id=? ORDER BY pu.id DESC");$u->execute([$t]);$c=$db->prepare("SELECT id,name,email FROM customers WHERE tenant_id=? AND deleted_at IS NULL ORDER BY name");$c->execute([$t]);$this->view('portal_admin/index',['title'=>'Customer Portal Access','portalUsers'=>$u->fetchAll(),'customers'=>$c->fetchAll()]);}
    public function create():void{$this->requireCsrf();if(!Auth::can('portal.manage'))Response::json(['success'=>false,'message'=>'Forbidden','errors'=>[]],403);$customer=(int)Request::input('customer_id');$name=trim((string)Request::input('name'));$email=strtolower(trim((string)Request::input('email')));$password=(string)Request::input('password');if(!$customer||$name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)Response::json(['success'=>false,'message'=>'Customer, name, email, password minimal 8 karakter wajib.','errors'=>[]],422);try{Database::connection()->prepare("INSERT INTO customer_portal_users(tenant_id,customer_id,name,email,password_hash,status,created_at,updated_at) VALUES(?,?,?,?,?,'active',NOW(),NOW())")->execute([Auth::tenantId(),$customer,$name,$email,password_hash($password,PASSWORD_DEFAULT)]);}catch(\Throwable $e){Response::json(['success'=>false,'message'=>'Unable to create portal access: '.$e->getMessage(),'errors'=>[]],422);}Response::json(['success'=>true,'message'=>'Customer portal access created.','data'=>['reload'=>true]]);}
}
